"""Layer resolver — picks the ordered list of template roots based on `harness.yaml`.

Composition order (later overrides earlier; per-file shadow, not body merge):

    base
    roles/<role>/                     for each role in harness.yaml roles
    stacks/<framework>/               for each stack
    integrations/doc-tracker/<n>/
    integrations/issue-tracker/<n>/
    integrations/design/<n>/          (only when role frontend or mobile)
    integrations/vcs/<n>/
    integrations/ci/<n>/
    governance/<profile>/
    .harness/overrides/                 if present in repo

The resolver does NOT touch the filesystem beyond checking that selected layer
directories exist; rendering and dedup are downstream.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from harness.config.models import HarnessConfig

# Default templates root (shipped as package data). Tests can override.
PACKAGE_ROOT = Path(__file__).resolve().parents[1]
DEFAULT_TEMPLATE_ROOT = PACKAGE_ROOT / "templates"


@dataclass(frozen=True)
class Layer:
    """A single layer in the composition stack."""

    label: str  # human-friendly id, e.g. "base", "stacks/nextjs"
    root: Path  # absolute path to layer directory (may not exist for stub layers)
    optional: bool = False  # if True, missing dir is silently skipped


class LayerResolutionError(RuntimeError):
    """Raised when a required layer directory does not exist on disk."""


def resolve_layers(
    config: HarnessConfig,
    template_root: Path | None = None,
    project_overrides_dir: Path | None = None,
) -> list[Layer]:
    """Return the ordered list of layers (base → overrides) for `config`.

    `template_root` defaults to the bundled `templates/` directory.
    `project_overrides_dir` is the repo-side overrides (`.harness/overrides/`); included only if it exists.
    """
    root = template_root or DEFAULT_TEMPLATE_ROOT
    layers: list[Layer] = [Layer("base", root / "base", optional=False)]

    # Roles AND stacks layers dropped (v0.2). Reasoning: roles duplicated other
    # layers; stack rules belong with the team. Composer still auto-synthesises
    # `<framework>-patterns` skill scaffolds per declared stack — teams fill the
    # body. Layer order: base → integrations → governance → project-overrides.

    integrations = config.integrations
    if integrations.doc_tracker != "local":
        layers.append(Layer(
            f"integrations/doc-tracker/{integrations.doc_tracker}",
            root / "integrations" / "doc-tracker" / integrations.doc_tracker,
            optional=True,
        ))
    if integrations.issue_tracker != "none":
        layers.append(Layer(
            f"integrations/issue-tracker/{integrations.issue_tracker}",
            root / "integrations" / "issue-tracker" / integrations.issue_tracker,
            optional=True,
        ))
    if integrations.design != "none":
        layers.append(Layer(
            f"integrations/design/{integrations.design}",
            root / "integrations" / "design" / integrations.design,
            optional=True,
        ))
    layers.append(Layer(
        f"integrations/vcs/{integrations.vcs}",
        root / "integrations" / "vcs" / integrations.vcs,
        optional=True,
    ))
    if integrations.ci != "none":
        layers.append(Layer(
            f"integrations/ci/{integrations.ci}",
            root / "integrations" / "ci" / integrations.ci,
            optional=True,
        ))
    if integrations.observability != "none":
        layers.append(Layer(
            f"integrations/observability/{integrations.observability}",
            root / "integrations" / "observability" / integrations.observability,
            optional=True,
        ))
    if integrations.comms != "none":
        layers.append(Layer(
            f"integrations/comms/{integrations.comms}",
            root / "integrations" / "comms" / integrations.comms,
            optional=True,
        ))

    layers.append(Layer(
        f"governance/{config.governance.profile}",
        root / "governance" / config.governance.profile,
        optional=False,  # governance must exist or generate will silently lose deny rules
    ))

    if project_overrides_dir is not None and project_overrides_dir.exists():
        layers.append(Layer("project-overrides", project_overrides_dir, optional=True))

    # validate required layers are present
    for layer in layers:
        if not layer.optional and not layer.root.exists():
            raise LayerResolutionError(
                f"required layer {layer.label!r} not found at {layer.root}. "
                f"Templates under templates/{layer.label}/ have not been authored yet."
            )

    return layers


def existing_layers(layers: list[Layer]) -> list[Layer]:
    """Filter to layers whose root actually exists on disk."""
    return [layer for layer in layers if layer.root.exists()]
